<script setup lang="ts">
import {installationTaskProgress,installationTaskStateLabel,installationTaskRemainingMinutes,type InstallationTask} from '#shared/types/tasks'
const props=defineProps<{task:InstallationTask;busy?:boolean;canPause?:boolean}>()
const emit=defineEmits<{cancel:[task:InstallationTask];confirm:[task:InstallationTask];'stop-waiting':[task:InstallationTask];remove:[task:InstallationTask];pause:[]}>()
const {t,formatLocale}=useAppLocale(),now=ref(Date.now())
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>timer=setInterval(()=>now.value=Date.now(),1000));onBeforeUnmount(()=>clearInterval(timer))
const percent=computed(()=>installationTaskProgress(props.task)),ps5=computed(()=>(props.task.consolePlatform||props.task.platform)==='ps5')
const stages=computed(()=>ps5.value?['Передача','Проверка','Регистрация']:['Подготовка','Скачивание','Установка'])
const step=computed(()=>{const x=props.task;if(x.state==='installed')return 3;if(x.state==='installing'&&(ps5.value||x.bytesSent>=x.size))return 2;if(ps5.value)return x.progressPhase==='device-check'?1:0;return ['receiving','sending','installing'].includes(x.state)?1:0})
const remaining=computed(()=>installationTaskRemainingMinutes(props.task,now.value))
const bytes=(n:number)=>`${(n/1024**3).toLocaleString(formatLocale.value,{maximumFractionDigits:2})} ${t('ГБ')}`
</script>
<template><article class="active-install-card glass-surface" :class="{problem:task.state==='unconfirmed'||task.state==='failed'}"><GlassArtwork :title="task.title" :cover="task.groupIconId?`/api/packages/${task.groupIconId}?asset=icon`:undefined"/><div class="active-install-main"><h3>{{task.title}}</h3><ContentTags :platform="task.platform||task.consolePlatform" :formats="task.format?[task.format]:[]"/><p class="active-install-bytes"><template v-if="task.progressPhase==='source-check'">{{t('Проверено')}}: </template>{{bytes(task.progressPhase==='source-check'?task.bytesChecked||0:task.bytesSent)}} / {{bytes(task.size)}}</p><div class="active-install-progress"><progress :value="percent" max="100" :aria-label="`${t('Прогресс')}: ${task.title}`"/><strong>{{Math.round(percent)}}%</strong></div><InstallationTransferSpeed :task="task"/><small v-if="remaining!==undefined">{{t('Осталось примерно')}} {{remaining}} {{t('мин')}}</small></div><div class="active-install-status"><div v-if="task.progressPhase==='source-check'" class="preflight-phase">◈ {{t('Проверка исходного файла')}}<small>{{t('Передача ещё не началась')}}</small></div><ol v-else class="installation-stages" :aria-label="t('Этапы установки')"><li v-for="(stage,i) in stages" :key="stage" :class="{done:i<step,current:i===step}" :aria-current="i===step?'step':undefined"><i>{{i<step?'✓':''}}</i><span>{{t(stage)}}</span></li></ol><p>{{t(installationTaskStateLabel(task))}} · {{t(task.detail)}}</p><small>{{task.transport==='service'?'PackageFlowService':'PyLoader'}} · {{ps5?'PS5':'PS4'}}</small><div class="active-install-actions"><button v-if="canPause" :disabled="busy" @click="emit('pause')">Ⅱ {{t('Пауза')}}</button><button v-if="task.canCancel" class="danger" :disabled="busy||task.cancelRequested" @click="emit('cancel',task)">× {{t(task.cancelRequested?'Отменяем…':'Отменить')}}</button><button v-if="task.canConfirm" :disabled="busy" @click="emit('confirm',task)">{{t('Установлено на PS5')}}</button><button v-if="task.canStopWaiting" :disabled="busy" @click="emit('stop-waiting',task)">{{t('Снять ожидание')}}</button><button v-if="task.canDismiss" :disabled="busy" @click="emit('remove',task)">{{t('Убрать задание')}}</button></div></div></article></template>
